// TH18 v1.00a st06bs.ecl.txt:618-760 (BossCard1) + 126-157 (Boss1Card_at).
// Source card "「無主への供物」", spell id 60, timeout 4200.
// Shell: control enemy (0,0) owns the spell and the 120-frame prep buffer; the
// real boss starts at the common Boss entry (0,128) and keeps source hitboxes.
// Source t0 = first frame of boss_card1; TIME_LIMIT = 120 + 4200 + 2.
const TIME_LIMIT: int = 4322;
const TH18_TALISMAN: int = 528; // source etSprite type 11, base radius 2.8
const HALF_TURN: int = 32768;

// Source B:136-139: ANIM(a=1), OFFSCREEN(300,b=0), WAIT(60), VELTIME(120,r=1).
// The birth ANIM retreat (-4*initial speed) is folded into sh_dist below.
// offscreen_keep 298: 300 minus the two same-tick effect-end reruns (WAIT, VELTIME).
xformdef TALISMAN_KEEP(unused: int) {
    offscreen_keep(298);
    @60 add_speed(0fx);        // explicit WAIT(60); birth animation itself omitted
    set_accel(0.006666fx);     // VELTIME: (1.0-0.2)/120 per tick along heading
    @120 set_accel(0fx);
}

// Source B:143-144: etCopy(1,0) plus etExSet(1,4,...,DELETE(a=0)).
xformdef TALISMAN_DELETE(unused: int) {
    offscreen_keep(298);
    @60 add_speed(0fx);
    set_accel(0.006666fx);
    @120 set_accel(0fx);
    set_life(1);               // DELETE at the end of the 180-frame EX program
}

// One Boss1Card_at call: one B-fan at dist 72 plus four 2B-fans at 88..136.
sub emit_one(color: int, n: int, step1: int) {
    // B:129 one %RANDF2 draw per call, shared by all five rings:
    // %C = ANGLE_PLAYER + pi + RANDF2*0.05235988 (3 degrees = 546 BAM).
    var aim: angle = atan2($player_y - $self_y, $player_x - $self_x);
    var ca: int = (aim as int) + HALF_TURN
                  + (rand(65536) - 32768) * 546 / 32768;
    // B:131-142 emitter 0: mode1 fixed fan, count B, step 2*F0, M=1 -> speed 0.2.
    // B:140-141 absolute offset = player, dist -72; ANIM retreat adds -0.8.
    sh_reset(0);
    sh_sprite(0, TH18_TALISMAN, color);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, 0.2fx, 0fx);
    sh_angle(0, ca as angle, (step1 * 2) as angle);
    sh_xform(0, TALISMAN_KEEP(0));
    sh_offset_abs(0, $player_x, $player_y);
    sh_dist(0, -72.8fx);
    sh_fire(0);
    // B:143-155 emitter 1: copied config, count 2B, step F0, four rings,
    // extra DELETE; ANIM retreat adds -0.8 to each source distance.
    sh_count(0, n * 2, 1);
    sh_angle(0, ca as angle, step1 as angle);
    sh_xform(0, TALISMAN_DELETE(0));
    sh_dist(0, -88.8fx);
    sh_fire(0);
    sh_dist(0, -104.8fx);
    sh_fire(0);
    sh_dist(0, -120.8fx);
    sh_fire(0);
    sh_dist(0, -136.8fx);
    sh_fire(0);
}

async sub boss_card1() {
    set_invuln(65535);
    set_hitbox(24fx);   // B:34 source 48x48 body box
    set_hurtbox(20fx);  // B:33 source 40x40 hurt box
    // B:656 flagSet(3) includes the no-body bit; B:711 flagClear(3) restores it.
    set_enemy_flag(ENEMY_NO_BODY, 1);

    var rank: int = global(GVAR_RANK);
    // B:662-666 diffI/diffF.
    var b: int = 12;
    var c: int = 12;
    var step1: int = 1638; // 0.15707964 rad
    var d1: int = 200;
    var d2: int = 190;
    var d3: int = 190;
    if rank == 1 { b = 20; c = 24; step1 = 964; d1 = 180; d2 = 170; d3 = 160; }
    if rank == 2 { b = 22; c = 26; step1 = 964; d1 = 170; d2 = 160; d3 = 160; }
    if rank == 3 { b = 24; c = 28; step1 = 964; d1 = 160; d2 = 150; d3 = 150; }
    // Phase-2 call count and remaining tail before the source 4200 timeout.
    var calls2: int = 12;
    var tail: int = 70;
    if rank == 1 { calls2 = 15; tail = 120; }
    if rank == 2 { calls2 = 16; tail = 60; }
    if rank == 3 { calls2 = 18; tail = 10; }

    // B:654 prelude: 180-frame quad-out move to (0,-192); first burst at t=90.
    move_to(180, 0fx, -192fx, EASE_QUAD_OUT);
    wait(90);
    // B:668-710 first F=2 pass, D=200/180/170/160 by rank.
    for i1 in 0..5 {
        var col1: int = 4;
        if i1 == 1 { col1 = 6; }
        if i1 == 2 { col1 = 10; }
        if i1 == 3 { col1 = 13; }
        if i1 == 4 { col1 = 2; }
        emit_one(col1, b, step1);
        if b < c { b = b + 1; }
        wait(d1);
    }
    // B:668-710 second F pass, D one step lower.
    for i2 in 0..5 {
        var col2: int = 4;
        if i2 == 1 { col2 = 6; }
        if i2 == 2 { col2 = 10; }
        if i2 == 3 { col2 = 13; }
        if i2 == 4 { col2 = 2; }
        emit_one(col2, b, step1);
        if b < c { b = b + 1; }
        wait(d2);
    }
    // B:711-715: body contact back on, snap to (128,-192), return to (0,128).
    set_enemy_flag(ENEMY_NO_BODY, 0);
    move_to(0, 128fx, -192fx, EASE_LINEAR);
    move_to(180, 0fx, 128fx, EASE_QUAD_OUT);
    // B:716-755 with G=100: five-call bodies every 5*D3 frames; the source
    // 4200 timeout cuts the loop, so only calls before t=4200 are kept.
    for i3 in 0..calls2 {
        var col3: int = 4;
        var k3: int = i3 % 5;
        if k3 == 1 { col3 = 6; }
        if k3 == 2 { col3 = 10; }
        if k3 == 3 { col3 = 13; }
        if k3 == 4 { col3 = 2; }
        emit_one(col3, b, step1);
        if b < c { b = b + 1; }
        if i3 < calls2 - 1 { wait(d3); }
    }
    wait(tail); // reach source t=4200; successor Boss2 is the segment boundary
    return;
}

async sub pattern() {
    wait(120); // prep buffer; attack starts on the next boss task frame
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_card1);
    loop { wait(1); }
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, 60, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    loop { wait(600); }
}
